/* --------------------------------------------------------------------------
   1. Переменные
   Пользовательские свойства объявлены на корневом элементе :root и доступны
   во всём файле через функцию var(). Одно изменение здесь меняет оформление
   всех страниц сайта.
   -------------------------------------------------------------------------- */
:root {
    --brand: #4f46e5;
    --brand-dark: #3730a3;
    --brand-soft: #eef2ff;
    --ink: #1f2937;
    --muted: #5b6472;
    --line: #d8dee9;
    --surface: #ffffff;
    --canvas: #f4f6fb;
    --radius: 12px;
    --shadow: 0 10px 24px rgba(31, 41, 55, 0.10);
    --font-text: "Segoe UI", Verdana, Arial, sans-serif;
    --font-code: "Consolas", "Courier New", monospace;
}


/* --------------------------------------------------------------------------
   2. Базовые стили документа
   Селекторы элементов обёрнуты в :where(). У него нулевой вес, поэтому
   собственные правила страниц, созданных в ЛР1–ЛР6, оказываются
   приоритетнее и не ломаются: файл задаёт оформление по умолчанию только там,
   где сама страница ничего не определила.
   -------------------------------------------------------------------------- */
:where(body) {
    background-color: var(--canvas);
    color: var(--ink);
    font-family: var(--font-text);
    font-size: 16px;
    line-height: 1.55;
}

/* 4.1. Селектор элемента: правило действует на все элементы blockquote сайта */
blockquote {
    margin: 0;
    padding: 12px 16px;
    border-left: 4px solid var(--brand);
    background-color: var(--brand-soft);
    color: #312e81;
    font-style: italic;
}

/* 4.2. Селектор класса: применяется к элементам с атрибутом class */
.demo-chip {
    display: inline-block;
    padding: 5px 12px;
    border-radius: 999px;
    background-color: #e0e7ff;
    color: #312e81;
    font-size: 0.85rem;
    font-weight: 600;
}

.demo-chip--alt {
    background-color: #fce7f3;
    color: #9d174d;
}

/* 4.3. Селектор идентификатора: применяется к единственному элементу с id */
#demo-target {
    margin: 0;
    padding: 10px 14px;
    border: 2px dashed var(--brand);
    border-radius: 8px;
    background-color: #eef2ff;
    font-weight: 600;
}

/* 4.4. Селектор потомка: любые p внутри .demo-tree, на любом уровне */
.demo-tree p {
    margin: 0 0 6px;
    padding: 6px 10px;
    background-color: #dcfce7;
}

/* 4.5. Селектор дочернего элемента: только p первого уровня внутри .demo-child */
.demo-child > p {
    margin: 0 0 6px;
    padding: 6px 10px;
    background-color: #fef3c7;
}

/* 4.6. Селекторы смежных элементов одного уровня */
.demo-siblings h4 {
    margin: 0 0 6px;
    font-size: 0.95rem;
}

/* знак + — только первый соседний абзац сразу после заголовка */
.demo-siblings h4 + p {
    padding: 6px 10px;
    background-color: #fee2e2;
}

/* знак ~ — все соседние абзацы после заголовка */
.demo-siblings h4 ~ p {
    border-bottom: 2px solid #ef4444;
}

/* 4.7. Селекторы атрибутов: значение атрибута href проверяется по началу */
.demo-link[href^="https"] {
    font-weight: 700;
}

.demo-link[href^="https"]::after {
    content: " ↗";
}

.demo-link[href^="#"] {
    color: #0f766e;
}

/* ==========================================================================
   styles.css — единый стилевой файл учебного сайта
   Лабораторная работа № 7 «Основы работы с CSS3»

   Файл подключается ко всем страницам, созданным в лабораторных работах 1–6,
   и к страницам самой седьмой работы:
       из папок ЛР1–ЛР6  —  <link rel="stylesheet" href="../ЛР7/styles.css">
       внутри папки ЛР7  —  <link rel="stylesheet" href="styles.css">

   Разделы файла:
       1. Переменные (пользовательские свойства)
       2. Базовые стили документа
       3. Стили сайта: шапка, навигация, карточки, подвал
       4. Демонстрация типов селекторов
       5. Адаптивность и печать
   ========================================================================== */


/* --------------------------------------------------------------------------
   1. Переменные
   Пользовательские свойства объявлены на корневом элементе :root и доступны
   во всём файле через функцию var(). Одно изменение здесь меняет оформление
   всех страниц сайта.
   -------------------------------------------------------------------------- */
:root {
    --brand: #4f46e5;
    --brand-dark: #3730a3;
    --brand-soft: #eef2ff;
    --ink: #1f2937;
    --muted: #5b6472;
    --line: #d8dee9;
    --surface: #ffffff;
    --canvas: #f4f6fb;
    --radius: 12px;
    --shadow: 0 10px 24px rgba(31, 41, 55, 0.10);
    --font-text: "Segoe UI", Verdana, Arial, sans-serif;
    --font-code: "Consolas", "Courier New", monospace;
}


/* --------------------------------------------------------------------------
   2. Базовые стили документа
   Селекторы элементов обёрнуты в :where(). У него нулевой вес, поэтому
   собственные правила страниц, созданных в ЛР1–ЛР6, оказываются
   приоритетнее и не ломаются: файл задаёт оформление по умолчанию только там,
   где сама страница ничего не определила.
   -------------------------------------------------------------------------- */
:where(body) {
    background-color: var(--canvas);
    color: var(--ink);
    font-family: var(--font-text);
    font-size: 16px;
    line-height: 1.55;
}

:where(h1, h2, h3, h4) {
    color: #1e1b4b;
    line-height: 1.25;
}

:where(a) {
    color: var(--brand);
    text-underline-offset: 3px;
}

:where(a:hover) {
    color: var(--brand-dark);
}

:where(table) {
    border-collapse: collapse;
}

:where(th, td) {
    padding: 6px 10px;
    border: 1px solid var(--line);
    text-align: left;
}

:where(th) {
    background-color: var(--brand-soft);
}

:where(code, kbd, samp, var) {
    font-family: var(--font-code);
}

:where(code) {
    padding: 1px 5px;
    border-radius: 4px;
    background-color: #f1f5f9;
}

:where(abbr[title]) {
    text-decoration: underline dotted;
    cursor: help;
}

:where(mark) {
    background-color: #fde68a;
}

/* Псевдоэлемент ::selection не оборачивается в :where(): спецификация
   запрещает псевдоэлементы внутри :where(), такое правило не действует. */
::selection {
    color: #ffffff;
    background-color: var(--brand);
}


/* --------------------------------------------------------------------------
   3. Стили сайта
   Компоненты оформлены селекторами классов с префиксом .site-, чтобы не
   пересекаться с классами прежних работ (.card, .header, .footer и т. п.).
   -------------------------------------------------------------------------- */

/* Страницы ЛР7 занимают всю ширину окна: внешний отступ body у них снят.
   У прежних страниц отступ браузера по умолчанию сохранён. */
.site {
    margin: 0;
}

/* Шапка сайта: селектор класса .site-header */
.site-header {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 18px;
    padding: 18px clamp(16px, 4vw, 40px);
    background-image: linear-gradient(120deg, #1e1b4b, var(--brand));
    color: #ffffff;
}

.site-brand {
    margin: 0;
    font-size: 1.15rem;
    font-weight: 700;
    letter-spacing: 0.02em;
}

.site-brand small {
    display: block;
    font-size: 0.78rem;
    font-weight: 400;
    opacity: 0.82;
}

/* Навигация: вложенные ссылки — селектор потомка и псевдокласс :hover */
.site-nav {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
}

.site-nav a {
    padding: 8px 14px;
    border-radius: 999px;
    color: #e0e7ff;
    font-size: 0.92rem;
    text-decoration: none;
}

.site-nav a:hover,
.site-nav a:focus-visible {
    background-color: rgba(255, 255, 255, 0.18);
    color: #ffffff;
}

.site-nav a[aria-current="page"] {
    background-color: #ffffff;
    color: var(--brand-dark);
}

.site-main {
    max-width: 1080px;
    margin: 0 auto;
    padding: 30px clamp(16px, 4vw, 32px) 56px;
}

.site-lead {
    max-width: 70ch;
    margin: 0 0 8px;
    color: var(--muted);
    font-size: 1.05rem;
}

/* Список карточек: сетка из автоматически подбираемых колонок */
.site-cards {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
    gap: 18px;
    margin: 26px 0;
    padding: 0;
    list-style: none;
}

.site-card {
    display: flex;
    flex-direction: column;
    gap: 8px;
    padding: 20px;
    border: 1px solid var(--line);
    border-radius: var(--radius);
    background-color: var(--surface);
    box-shadow: var(--shadow);
}

.site-card h3 {
    margin: 0;
    font-size: 1.05rem;
}

.site-card p {
    margin: 0;
    color: var(--muted);
    font-size: 0.92rem;
}

.site-card a {
    margin-top: auto;
    font-weight: 700;
    text-decoration: none;
}

.site-tag {
    align-self: flex-start;
    padding: 2px 10px;
    border-radius: 999px;
    background-color: var(--brand-soft);
    color: var(--brand-dark);
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.06em;
    text-transform: uppercase;
}

.site-note {
    margin: 22px 0;
    padding: 14px 18px;
    border-left: 4px solid var(--brand);
    border-radius: 0 var(--radius) var(--radius) 0;
    background-color: var(--brand-soft);
    color: #312e81;
}

.site-button {
    display: inline-block;
    padding: 9px 18px;
    border-radius: 999px;
    background-color: var(--brand);
    color: #ffffff;
    font-weight: 700;
    text-decoration: none;
}

.site-button:hover {
    background-color: var(--brand-dark);
    color: #ffffff;
}

.site-footer {
    padding: 22px clamp(16px, 4vw, 40px);
    border-top: 4px solid var(--brand);
    background-color: #1e1b4b;
    color: #c7d2fe;
    font-size: 0.92rem;
}

.site-footer a {
    color: #ffffff;
}

/* --------------------------------------------------------------------------
   5. Адаптивность и печать
   -------------------------------------------------------------------------- */
@media (max-width: 720px) {
    .site-header {
        flex-direction: column;
        align-items: flex-start;
    }

    .demo-grid {
        grid-template-columns: 1fr;
    }
}

@media print {
    .site-header {
        background: none;
        color: #000000;
    }

    .site-nav {
        display: none;
    }
}
